css=r'''<style>
/* MUTATION 17 // ARC INTELLIGENCE + CINEMATIC MILESTONES */
.arc17-hero{margin-top:14px;position:relative;min-height:330px;border-radius:24px;overflow:hidden;border:1px solid rgba(150,110,255,.28);background:#03020a;box-shadow:0 25px 100px rgba(60,20,130,.22)}.arc17-hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:opacity .8s,transform 9s}.arc17-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(3,2,9,.95),rgba(3,2,9,.34),rgba(3,2,9,.76));pointer-events:none}.arc17-copy{position:relative;z-index:2;min-height:330px;padding:28px;display:flex;flex-direction:column;justify-content:flex-end}.arc17-kicker{font:700 9px 'DM Mono';letter-spacing:.25em;color:#a88aff}.arc17-title{font:900 clamp(24px,5vw,44px) Orbitron;letter-spacing:.06em;margin:7px 0}.arc17-sub{max-width:700px;color:#c5bdd4;font-size:11px;line-height:1.6}.arc17-chips{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.arc17-chip{padding:7px 10px;border:1px solid rgba(160,120,255,.24);border-radius:999px;background:rgba(6,4,15,.7);font:700 8px 'DM Mono';letter-spacing:.08em}.arc17-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:12px;margin-top:14px}.arc17-panel{padding:16px;border:1px solid rgba(150,110,255,.18);border-radius:18px;background:rgba(255,255,255,.025)}.arc17-panel h4{margin:0;font:800 11px Orbitron;letter-spacing:.08em}.arc17-panel p{font-size:10px;color:#9d95aa;line-height:1.55}.intel-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px}.intel-kpi{padding:11px;border-radius:13px;border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.02)}.intel-kpi span{display:block;font:700 8px 'DM Mono';color:#81788f;letter-spacing:.1em}.intel-kpi b{display:block;font:800 17px Orbitron;margin-top:4px}.intel-directive{margin-top:12px;padding:14px;border-radius:15px;border:1px solid rgba(140,110,255,.24);background:linear-gradient(135deg,rgba(100,60,190,.1),rgba(255,255,255,.02))}.intel-directive .id-label{font:800 8px 'DM Mono';letter-spacing:.18em;color:#9f8cff}.intel-directive strong{display:block;font:800 14px Orbitron;margin-top:5px}.intel-directive small{display:block;color:#aaa2b5;margin-top:5px;line-height:1.5}.intel-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.signal-list{display:grid;gap:7px;margin-top:10px}.signal{display:flex;justify-content:space-between;gap:10px;padding:9px 10px;border-radius:11px;background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.05);font-size:9px}.signal b{color:#cbbcff}.chapter-rail{display:grid;grid-template-columns:repeat(7,1fr);gap:5px;margin-top:14px}.chapter-node{min-height:86px;padding:8px;border:1px solid rgba(255,255,255,.06);border-radius:13px;background:rgba(255,255,255,.018);cursor:pointer;position:relative;overflow:hidden;color:inherit;text-align:left}.chapter-node.active{border-color:rgba(165,130,255,.5);box-shadow:0 0 28px rgba(100,70,200,.12)}.chapter-node.complete{border-color:rgba(110,230,190,.35)}.chapter-node b{display:block;font:800 9px Orbitron}.chapter-node small{display:block;color:#81798e;font-size:7px;margin-top:5px;line-height:1.35}.chapter-node span{display:block;margin-top:7px;font:700 8px 'DM Mono';color:#bcaaff}.milestone-grid17{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:12px}.milestone-card17{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.07);border-radius:16px;background:#05040d;min-height:190px;padding:0;cursor:pointer;color:inherit;text-align:left}.milestone-card17 img{width:100%;height:190px;object-fit:cover;opacity:.58}.milestone-card17 .mc17{position:absolute;inset:0;padding:12px;display:flex;flex-direction:column;justify-content:flex-end;background:linear-gradient(180deg,transparent 25%,rgba(2,2,8,.94))}.milestone-card17 b{font:800 10px Orbitron}.milestone-card17 small{font-size:8px;color:#aaa1b2;margin-top:4px}.milestone-card17.locked{filter:grayscale(.65);opacity:.5}.milestone-card17.current{border-color:rgba(170,130,255,.55);box-shadow:0 0 28px rgba(120,80,220,.15)}.reflection17{margin-top:12px;padding:16px;border:1px solid rgba(150,110,255,.18);border-radius:18px;background:rgba(255,255,255,.02)}.reflection17 textarea{min-height:90px;margin-top:8px}.timeline17{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:10px}.timeline-event17{padding:10px;border-radius:12px;background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.05);font-size:8px}.timeline-event17 b{display:block;font:800 9px Orbitron}.timeline-event17 small{display:block;color:#82798c;margin-top:4px;line-height:1.45}.arc17-modal{position:fixed;inset:0;z-index:90;background:rgba(1,1,5,.86);backdrop-filter:blur(16px);display:none;place-items:center;padding:18px}.arc17-modal.open{display:grid}.arc17-modal-box{width:min(980px,100%);max-height:92vh;overflow:auto;border:1px solid rgba(170,130,255,.32);border-radius:26px;background:#05040d;box-shadow:0 40px 140px #000;overflow:hidden}.arc17-modal-box img{width:100%;height:min(55vh,500px);object-fit:cover;display:block}.arc17-modal-copy{padding:20px}.arc17-modal-copy h2{font:900 28px Orbitron;margin:0}.arc17-modal-copy p{color:#aaa2b4;font-size:11px;line-height:1.7}.arc17-modal-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}@media(max-width:900px){.arc17-grid{grid-template-columns:1fr}.milestone-grid17{grid-template-columns:repeat(2,1fr)}.chapter-rail{grid-template-columns:repeat(4,1fr)}.intel-kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.milestone-grid17{grid-template-columns:1fr}.chapter-rail{grid-template-columns:repeat(2,1fr)}.timeline17{grid-template-columns:1fr 1fr}.arc17-hero,.arc17-copy{min-height:290px}}
</style>'''
