modal='<div class="arc17-modal" id="arc17Modal"><div class="arc17-modal-box"><img id="arc17ModalImg" src="assets/arc_awaken.webp" alt="Arc milestone"><div class="arc17-modal-copy"><div class="arc17-kicker" id="arc17ModalKicker">ARC MILESTONE</div><h2 id="arc17ModalTitle">AWAKENING</h2><p id="arc17ModalText">A milestone room in the Winter Arc.</p><div class="arc17-modal-actions"><button class="control-btn primary" onclick="closeArc17Modal()">RETURN TO ARC</button><button class="control-btn" onclick="markMilestoneViewed17()">SEAL AS VIEWED</button></div></div></div></div>'
