js=r'''/* MUTATION 17 // ARC INTELLIGENCE ENGINE */
const MILESTONES17=[{day:1,title:'AWAKENING',file:'assets/milestone_01.webp',desc:'The first mark. Establish the baseline without pretending you are already strong.'},{day:10,title:'FOUNDATION',file:'assets/milestone_10.webp',desc:'Calibration becomes a pattern. Compare what repeated instead of what looked impressive.'},{day:25,title:'PRESSURE',file:'assets/milestone_25.webp',desc:'The first major pressure gate. Reliability matters more than a perfect streak.'},{day:45,title:'EVOLUTION',file:'assets/milestone_45.webp',desc:'The midpoint comparison. Your earlier baseline becomes evidence, not identity.'},{day:65,title:'ELITE',file:'assets/milestone_65.webp',desc:'Capability now has history. The system begins emphasizing output and proof.'},{day:80,title:'MONARCH',file:'assets/milestone_80.webp',desc:'The remaining distance becomes visible. Protect the capabilities you built.'},{day:90,title:'ASCENSION',file:'assets/milestone_90.webp',desc:'The final chamber is an audit of what actually changed.'}];
function initArc17(){if(!state.arc17)state.arc17={lastSignal:null,accepted:[],reflections:{},viewed:[],chapterSeen:{},lastDirective:null};}
function arc17Metrics(){initArc17();const d=currentDay()+1,start=Math.max(0,d-7);let done=0,total=0;for(let i=start;i<d;i++){done+=dayCount(i);total+=5;}const completion=total?done/total:0,practice=(state.practiceLog||[]).slice(-14).reduce((s,x)=>s+Number(x.minutes||0),0),evidence=(state.evidence16||[]).length,projects=(state.projects16||[]).length,momentum=Math.min(20,Math.max(0,Number(state.streak||0)));const signal=Math.round(completion*45+Math.min(20,practice/60)+Math.min(15,evidence*2)+Math.min(10,projects*2)+Math.min(10,momentum));const pressure=Math.min(99,Math.round((d/90)*55+(1-completion)*35+Math.min(10,(state.threat||0)/10)));const readiness=Math.max(0,Math.min(100,Math.round(signal*.75+Math.min(25,evidence*3))));return{d,completion,practice,evidence,projects,momentum,signal,pressure,readiness,baseline:signal<20?'LOW':signal<45?'FORMING':signal<70?'STABLE':'ASCENDING'};}
function arc17Directive(m){const ch=chapterForDay(m.d).name;if(m.completion<.35)return{type:'STABILIZE',title:'REBUILD THE BASELINE',desc:'Your recent execution is uneven. Choose one small real-world action and make it repeatable before increasing pressure.'};if(m.evidence<2&&m.d>7)return{type:'PROVE',title:'CREATE A RECEIPT',desc:'Your activity is ahead of your evidence. Record something concrete you actually produced.'};if(m.practice<120&&m.d>10)return{type:'TRAIN',title:'DEEPEN ONE CAPABILITY',desc:'Your capability record needs deliberate practice. Log a focused session tied to something you are building.'};if(ch==='Pressure'||ch==='Evolution')return{type:'PRESSURE',title:'RAISE THE OUTPUT BAR',desc:'Your baseline has formed. Take one task slightly beyond what was comfortable last chapter.'};if(ch==='Elite'||ch==='Monarch')return{type:'PRESERVE',title:'PROTECT THE CAPABILITY',desc:'Do not trade a hard-earned capability for novelty. Repeat, ship, and document what now feels normal.'};if(ch==='Ascension')return{type:'AUDIT',title:'PREPARE THE FINAL DOSSIER',desc:'Collect the strongest projects, receipts and before/after evidence. The Arc is becoming a record.'};return{type:'BUILD',title:'BUILD THE NEXT LAYER',desc:'Keep the current pattern alive and add one deliberate improvement.'};}
function acceptArcDirective17(){const m=arc17Metrics(),q=arc17Directive(m);state.customQuests=Array.isArray(state.customQuests)?state.customQuests:[];state.customQuests.push({text:q.title+' — '+q.desc,done:false,created:new Date().toISOString(),day:m.d,arc17:true});state.customQuests=state.customQuests.slice(-40);state.arc17.accepted.push({day:m.d,title:q.title,time:Date.now()});state.arc17.lastDirective=q.title;persist();addEvent('Arc directive accepted · '+q.title,'⌁');renderAll();toast('ARC DIRECTIVE ACCEPTED',q.title+' entered the active quest layer.');}
function refreshArcIntel17(){renderArc17();toast('ARC RECALCULATED','The intelligence layer re-read your recent pattern.');}
function openArc17Milestone(day){const m=MILESTONES17.find(x=>x.day===day);if(!m)return;if(day>currentDay()+1){toast('MILESTONE LOCKED','Reach Day '+String(day).padStart(2,'0')+' before entering this chamber.');return;}document.getElementById('arc17ModalImg').src=m.file;document.getElementById('arc17ModalTitle').textContent='DAY '+String(day).padStart(2,'0')+' // '+m.title;document.getElementById('arc17ModalText').textContent=m.desc;document.getElementById('arc17Modal').classList.add('open');state.arc17.viewed=Array.from(new Set([...(state.arc17.viewed||[]),day]));persist();}
function closeArc17Modal(){document.getElementById('arc17Modal')?.classList.remove('open');}function markMilestoneViewed17(){addEvent('Milestone viewed · '+(document.getElementById('arc17ModalTitle')?.textContent||'MILESTONE'),'✦');persist();toast('MILESTONE ARCHIVED','The cinematic room is now part of your Arc memory.');closeArc17Modal();renderArc17();}
function sealReflection17(){initArc17();const d=currentDay()+1,ch=chapterForDay(d).name,v=(document.getElementById('reflection17Text')?.value||'').trim();if(v.length<12){toast('REFLECTION TOO SHORT','Write at least a few honest lines before sealing the chapter.');return;}state.arc17.reflections[ch]={day:d,text:v,time:new Date().toISOString()};state.proofs=(state.proofs||0)+1;state.xp+=20;persist();renderAll();toast('CHAPTER REFLECTION SEALED',ch+' is now part of the permanent Arc record.');}
function renderArc17(){initArc17();const m=arc17Metrics(),q=arc17Directive(m),ch=chapterForDay(m.d),scene=document.getElementById('arc17Scene');if(scene){const map={Awakening:'arc_awaken',Foundation:'arc_foundation',Pressure:'arc_pressure',Evolution:'arc_evolution',Elite:'arc_elite',Monarch:'arc_monarch',Ascension:'arc_ascension'};scene.src='assets/'+map[ch.name]+'.webp';}const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};set('arc17Title',ch.name.toUpperCase()+' // '+q.type);set('arc17Sub',ch.tone+' '+q.desc);set('arc17ChapterChip',ch.name.toUpperCase());set('arc17DayChip','DAY '+String(m.d).padStart(2,'0'));set('arc17ModeChip',q.type);set('arc17Signal',String(m.signal).padStart(2,'0'));set('arc17Baseline',m.baseline);set('arc17Pressure',String(m.pressure).padStart(2,'0'));set('arc17Readiness',m.readiness+'%');set('arc17DirectiveType',q.type+' // ADAPTIVE DIRECTIVE');set('arc17Directive',q.title);set('arc17DirectiveDesc',q.desc);const sg=document.getElementById('arc17Signals');if(sg)sg.innerHTML=[['7-DAY EXECUTION',Math.round(m.completion*100)+'%'],['PRACTICE LOAD',m.practice+' MIN'],['PROOF RECEIPTS',m.evidence],['PROJECT DOSSIERS',m.projects],['MOMENTUM',m.momentum+' DAYS']].map(x=>`<div class="signal"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');const rail=document.getElementById('chapterRail17');if(rail)rail.innerHTML=CHAPTERS.map(c=>{const active=m.d>=c.from&&m.d<=c.to,done=m.d>c.to;return `<button class="chapter-node ${active?'active':''} ${done?'complete':''}" onclick="openArc17Milestone(${c.from})"><b>${c.name.toUpperCase()}</b><small>D${String(c.from).padStart(2,'0')} — D${String(c.to).padStart(2,'0')}</small><span>${active?'ACTIVE':done?'COMPLETE':'LOCKED'}</span></button>`}).join('');const mg=document.getElementById('milestoneGrid17');if(mg)mg.innerHTML=MILESTONES17.map(x=>{const unlocked=x.day<=m.d,viewed=(state.arc17.viewed||[]).includes(x.day);return `<button class="milestone-card17 ${unlocked?'':'locked'} ${x.day===m.d?'current':''}" onclick="openArc17Milestone(${x.day})"><img src="${x.file}" alt="${x.title}"><div class="mc17"><b>DAY ${String(x.day).padStart(2,'0')} // ${x.title}</b><small>${unlocked?(viewed?'VIEWED · ENTER AGAIN':'ENTER CHAMBER'):'LOCKED · REACH DAY '+x.day}</small></div></button>`}).join('');const tl=document.getElementById('arc17Timeline'),events=(state.events||[]).slice(-5).reverse();if(tl)tl.innerHTML=(events.length?events:[{text:'The Arc is waiting for its first recorded event.'}]).map(e=>`<div class="timeline-event17"><b>${e.icon||'·'} EVENT</b><small>${escapeHTML(e.text||'Arc event')}</small></div>`).join('');const ref=document.getElementById('reflection17Text'),rs=document.getElementById('reflection17Status'),existing=state.arc17.reflections[ch.name];if(ref&&document.activeElement!==ref)ref.value=existing?.text||'';if(rs)rs.textContent=existing?'SEALED · '+existing.time:'NO REFLECTION SEALED';state.arc17.lastSignal=m.signal;state.arc17.lastDirective=q.title;persist();}
'''
pos=txt.rfind('</script>'); txt=txt[:pos]+js+'\n'+txt[pos:]
old='renderHeader();renderDays();renderQuests();renderStats();renderCharacterStatus();renderMetrics();renderHabits();renderAchievements();renderJournal();renderLog();renderV6();renderShadowSystems();renderShadowEngine();drawChart();'; new=old.replace('renderShadowEngine();','renderShadowEngine();renderArc17();'); txt=txt.replace(old,new,1)
HTML.write_text(txt)
p=ROOT/'app/build.gradle';s=p.read_text().replace('versionCode 12','versionCode 13').replace("versionName '3.0.0'","versionName '3.1.0'");p.write_text(s)
rp=ROOT/'README.md';rp.write_text(rp.read_text()+'\n## Mutation 17 — Arc Intelligence + Cinematic Milestones\n- Adaptive real-life Arc Intelligence engine, chapter rail, adaptive directives, cinematic milestone chambers, sealed chapter reflections, Arc memory timeline.\n- 14 chapter/milestone scenes.\n- Android 3.1.0 / versionCode 13.\n')
# syntax check
scripts=re.findall(r'<script[^>]*>(.*?)</script>',txt,re.S); Path('/tmp/shadow17.js').write_text('\n'.join(scripts));r=subprocess.run(['node','--check','/tmp/shadow17.js'],capture_output=True,text=True);print('NODE',r.returncode,r.stderr[:1500]);print('HTML',HTML.stat().st_size)
